// The public half of `hostNotes.ts`: the agent's own mark, vendored locally.
//
// `data/brand-logos.json` is generated by `scripts/gen_brand_logos.mjs` from
// `public/brands/` — it is a list of what is actually on disk, so this file
// can promise a URL only because the file behind it exists. Nothing here is
// fetched at runtime or at build time: every asset is committed, the same way
// the fonts are, so the export never makes a network request it can't make.

import brandLogos from "../data/brand-logos.json";

export interface BrandLogo {
  /** Local path, e.g. `/brands/cursor.svg`. */
  src: string;
  /** width ÷ height, or null when the dimensions could not be read. */
  aspect: number | null;
  /**
   * True when the asset is square enough to fill a tile (0.6–1.75).
   *
   * False means it is a wordmark or a very wide strip. Forcing one into a
   * square tile renders it as an unreadable sliver, so callers that need a
   * tile should show a letter mark instead — see `AgentLogo`.
   */
  square: boolean;
}

/**
 * The agent's official logo, or `null` when we have none.
 *
 * `null` is a first-class result, not a gap to paper over: the caller draws a
 * neutral letter mark instead, and we would rather show no logo than a logo
 * we cannot attribute to the product's own site.
 */
export function brandLogo(id: string): BrandLogo | null {
  const entry = (brandLogos as Record<string, BrandLogo>)[id];
  return entry ?? null;
}

/** How many agents currently have a vendored mark (surfaced in reviews so a
 *  near-empty manifest is visible rather than assumed to be complete). */
export function brandLogoCount(): number {
  return Object.keys(brandLogos).length;
}
